-- Import the second flattened source as 20 individually selectable Lily facts.
-- A lost heading is removed; one obsolete racial label is replaced with
-- neutral wording while retaining the source's historical meaning.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (809, $$Экзаменационный стресс: Традиция публичных выпускных экзаменов зародилась в римских школах риторики. Ученики были обязаны произнести сложнейшую речь-суждение (контроверсию) перед собранием родителей и строгих критиков, что проверяло их психологическую устойчивость.$$),
  (810, $$Иллюстрированный букварь: В Александрии в I веке до н.э. появились первые рукописи алфавитов, где каждая буква была нарисована в виде животного или предмета (например, Альфа — в виде головы быка), помогая маленьким детям соотносить абстрактные символы с реальностью.$$),
  (811, $$Майевтика (Сократовские дебаты): Метод обучения, при котором учитель не дает готовых догм, а серией логических вопросов заставляет ученика самого родить знание, признан основой современной интерактивной педагогики.$$),
  (812, $$Басни Эзопа как этический код: Использование коротких историй с моралью для обучения дошкольников языку и базовой этике — метод, разработанный Квинтилианом в учебнике «Обучение оратора».$$),
  (813, $$Otium cum dignitate (Умный досуг): Латинский концепт, детально описанный Цицероном, доказывает, что истинный отдых свободного человека — это не безделье, а чтение, самоанализ и созидание, что легло в основу европейской концепции саморазвития.$$),
  (814, $$Антропоморфизм в детских сказках: Наша привычка наделять животных характерами (заяц — трус, осел — упрямец) зафиксирована в трактате Элиана «О свойствах животных» (III в. н.э.).$$),
  (815, $$Написание Эссе: Современные стандарты школьных эссе-рассуждений строятся по правилам прогимнасмаг — античных методичек по развитию речи для подростков.$$),
  (816, $$Калокагатия (Гармоничное развитие): Греческий концепт, описанный Платоном, согласно которому человек должен одновременно развивать разум (философия, музыка) и тело (гимнастика), является базой современных систем образования.$$),
  (817, $$Сюжетный код «Злой мачехи»: Архетип злой мачехи, преследующей детей мужа ради своих амбиций, зародился в трагедии Еврипида «Медея» и его утерянной пьесе «Эгей».$$),
  (818, $$Происхождение слова «Каникулы»: Буквально переводится с латыни как «собачьи дни» (Dies caniculares). Римляне называли так самый жаркий период лета (конец июля — август), когда на небе восходила звезда Сириус (Каникула — Маленькая собачка), и занятия в школах отменялись из-за зноя.$$),
  (819, $$Пернатая пчела Вергилия: Из-за ошибки византийского переписчика, перепутавшего в рукописи «Георгик» буквы «p» и «v», слово Apes (пчелы) превратилось в Aves (птицы). Это привело к тому, что средневековые монахи писали абсурдные научные трактаты о «невидимых поющих птицах Рима, собирающих нектар».$$),
  (820, $$Смертельный смех Хрисиппа: Античный философ-стоик Хрисипп умер от смеха, наблюдая, как его осел ест инжир. Философ крикнул рабу: «А теперь дай ему выпить чистого вина, чтобы запить ягоды!», зашелся в припадке хохота и скончался от инсульта.$$),
  (821, $$Цензура Октавиана Августа: Император Октавиан лично нарушил посмертное завещание Вергилия, приказавшего сжечь рукопись «Энеиды» из-за её стилистического несовершенства. Август конфисковал свитки, нанял редакторов Вария и Тукку и приказал издать книгу, создав главный литературный памятник империи.$$),
  (822, $$Лицемерие Сенеки: Великий философ-стоик, проповедовавший отказ от материальных благ в «Письмах к Луцилию», был одним из богатейших людей Рима. Его состояние составляло 300 миллионов сестерциев, и он давал кредиты под грабительские проценты провинциям, что вызвало восстание в Британии. Судебные обвинения в лицемерии преследовали его всю жизнь.$$),
  (823, $$Истинное имя Гомера: В античных филологических хрониках Прокла утверждается, что настоящее имя поэта было Мелесиген (рожденный у реки Мелес), а имя «Гомер» он получил на ионийском диалекте, так как оно означало «слепец» или «идущий за напарником».$$),
  (824, $$Парадокс Платона против книг: Записав миллионы слов своих диалогов, Платон в диалоге «Федр» устами Сократа жестко критикует письменность. Он утверждает, что книги убивают память человека, создают иллюзию знания и не могут ответить на вопросы читателя, в отличие от живой беседы.$$),
  (825, $$Литературная война Теренция: Римский комедиограф Теренций (II в. до н.э.) превратил прологи к своим пьесам в трибуну для судов с критиками. Он публично высмеивал старого драматурга Луция Ланувина, обвинявшего его в краже греческих сюжетов.$$),
  (826, $$Научные суеверия Плиния: Автор первой 37-томной энциклопедии Плиний Старший погиб при извержении Везувия из-за научного любопытства. При этом в своей «Естественной истории» он зафиксировал рецепты лечения слепоты кровью дракона и инструкции по защите полей от града с помощью шкуры крокодила.$$),
  (827, $$Литературный рэкет Марциала: Римский поэт Марциал зарабатывал шантажом: он писал ядовитые эпиграммы о пороках патрициев (не называя имен), и богачи платили ему огромные деньги (клиентские выплаты), чтобы он случайно не вывел их под узнаваемыми масками в следующем свитке.$$),
  (828, $$Ранний пример работы за автора в Риме: Ювенал в «Сатирах» жестко высмеивал богатых нуворишей, которые скупали образованных греческих рабов-поэтов, заставляли их писать стихи и оды, а затем декламировали их в салонах, выдавая за свои собственные произведения ради повышения социального статуса.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  'LITERATURE',
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;

-- Keep the existing editorial pause for Russia-, Russian-, USSR-, and
-- Soviet-related cards reversible: records remain stored but not delivered.
UPDATE "philology_facts"
SET "isActive" = FALSE, "updatedAt" = CURRENT_TIMESTAMP
WHERE "isActive" = TRUE
  AND "text" ~* '(росси|русск|ссср|советск|большевик|петроград|кремл|сталин|пастернак|достоевск|толст|пушкин|гогол|лермонтов|чехов|есенин|маяковск|тургенев|некрасов|гумилев|ахматов|мандельштам|зощенко|салтыков|жуковск|грибоедов|булгаков|бунин|куприн|горьк|фет|фонвизин|тютчев|жданов|солженицын|стругацк|ильф|петров|набоков|чуковск|крылов|беляев|акунин|гайдар|блок|волошин|бендер|ппш|живаго|облонск|мюнхгаузен)';
